+  public async listMessages(actor: Actor, input: Omit<ListMessagesInput, 'projectId'>): Promise<Page<Message>> {
+    await this.authorize(actor, 'message:read', actor.projectId, input.inboxId);
+    await this.requireInbox(actor.projectId, input.inboxId);
+    const limit = Math.min(100, Math.max(1, input.limit ?? 25));
+    const messages = await this.store.listMessages(actor.projectId, input.inboxId, input);
+    const start = input.cursor ? Math.max(0, messages.findIndex((message) => message.id === decodeCursor(input.cursor)) + 1) : 0;
+    const items = messages.slice(start, start + limit);
+    return {
+      items,
+      nextCursor: start + limit < messages.length && items.length ? encodeCursor(items.at(-1)!.id) : undefined,
+    };
+  }
